result = 0
if not employee.rap_excluded:
    version = employee.current_version_id
    if version:
        # Check include_in: skip period if not applicable
        apply = True
        rap_config = version.rap_setup_id
        if rap_config and rap_config.include_in and payslip.date_from:
            day = payslip.date_from.day
            if rap_config.include_in == 'first' and day > 15:
                apply = False
            elif rap_config.include_in == 'second' and day <= 15:
                apply = False
        if apply:
            if version.rap_manual:
                result = -round(abs(version.amount_rap_manual), 2)
            elif version.rap_fee:
                result = -round(abs(version.rap_fee), 2)
            else:
                period_days = (payslip.date_to - payslip.date_from).days + 1 if payslip.date_from and payslip.date_to else 15
                if period_days > 16:
                    result = -round(abs(version.rap_foviif_amount_monthly or 0), 2)
                else:
                    result = -round(abs(version.rap_foviif_amount_biweekly or 0), 2)

result = 0
if not employee.rap_excluded:
    year = payslip.date_to.year if payslip.date_to else 2026
    rap_settings = payslip.env['l10n.hn.rap.settings'].search([
        ('year', '=', year),
        ('state', '=', 'validated'),
        ('company_id', '=', payslip.company_id.id)
    ], limit=1)

    if rap_settings:
        base = categories.get('BASIC', 0)

        if payslip.date_from and payslip.date_to:
            period_days = (payslip.date_to - payslip.date_from).days + 1
        else:
            period_days = 15

        floor = rap_settings.get_foviif_floor_for_period(period_days)

        if base > floor:
            result = round(base * (rap_settings.foviif_employer_rate / 100.0), 2)

